function renderSetlist(){ $('#setlist').innerHTML=songs.map((s,i)=>`<button class="set-item ${s===song?'active':''}" data-song="${s.id}"><span class="set-number">0${i+1}</span><span class="set-info"><strong>${esc(s.title)}</strong>${s.sub?`<small>${esc(s.sub)}</small>`:''}</span></button>`).join('');document.querySelectorAll('.set-item').forEach(b=>b.onclick=async()=>{const next=songs.find(x=>x.id===b.dataset.song);if(!next||next===song)return;playing=false;clearInterval(timer);silenceSynth();song=next;positionSec=0;currentSection=0;events=[];lyrics=[];songSeconds=0;measureInfo={};lastRenderedMeasure=0;lastRenderedSection=-1;$('#play').textContent='▶';$('#score-status').textContent='正在載入新曲目…';await renderAll();syncUi();});}
