const drumName=m=>({36:'kick',35:'kick',38:'snare',40:'snare',42:'closed-hat',44:'closed-hat',46:'open-hat',49:'crash',57:'crash',51:'ride',45:'tom',47:'tom',48:'tom',50:'tom'}[m]||'kick');
function drumArrangementAllowed(event){if(song.id!=='impossible-love')return true;if(event.measure<29)return false;if(event.measure<53&&[42,44,46,49,51,57].includes(event.midi))return false;return true;}
async function playAudio(){await loadSoundfont();await audioCtx.resume();silenceSynth();await resetSynth();playRate=Number($('#bpm').value)/song.bpm;const now=sfSynth.currentTime+.12,offset=positionSec;sfSynth.processMessage([0xC0,0],0,{time:now});sfSynth.processMessage([0xC1,48],0,{time:now});sfSynth.processMessage([0xB0,7,127],0,{time:now});sfSynth.processMessage([0xB0,11,127],0,{time:now});sfSynth.processMessage([0xB1,7,92],0,{time:now});sfSynth.processMessage([0xB1,11,100],0,{time:now});sfSynth.processMessage([0xB9,7,90],0,{time:now});sfSynth.processMessage([0xB9,11,95],0,{time:now});events.filter(e=>e.sec>=offset&&trackEnabled[e.part]&&(e.part!==2||drumArrangementAllowed(e))).forEach(e=>{const when=now+(e.sec-offset)/playRate,channel=e.part===2?9:e.part,rawMidi=e.part===1&&song.organHighCut&&e.midi>=song.organHighCut?e.midi-12:e.midi;let velocity=e.velocity==null?(e.part===0?100:e.part===1?105:80):e.velocity;if(e.part===2){const n=e.midi;velocity=n===36||n===35?95:n===38||n===37||n===40?88:/^(42|44|46)$/.test(String(n))?52:78;}sfSynth.processMessage([0x90|channel,rawMidi,velocity],0,{time:when});sfSynth.processMessage([0x80|channel,rawMidi,0],0,{time:when+e.length/playRate});});playStartedAt=performance.now();$('#score-status').textContent=trackEnabled.some(Boolean)?'播放中 · FluidR3 GM SF2（三軌）':'播放中 · 所有聲部已關閉';}
function syncScoreCursor(){if(!osmd?.cursor?.iterator)return;const target=Math.min(87,Math.max(1,Math.floor(positionSec/songSeconds*87)+1));try{while(scoreCursorMeasure<target&&!osmd.cursor.iterator.endReached){osmd.cursor.nextMeasure();scoreCursorMeasure++}while(scoreCursorMeasure>target){osmd.cursor.previousMeasure();scoreCursorMeasure--}osmd.cursor.update();osmd.cursor.show()}catch(error){console.warn('OSMD cursor update failed',error)}}
function renderLiveArrangement(measure){const info=measureInfo[measure]||{};const section=song.sections[currentSection]||['',1,1];const sectionName=section[0].split(' · ')[1]||section[0];const direction={N:'保持低密度：鋼琴留空間，弦樂只托長音，鼓組休息或不進。',Verse:'以穩定拍點托住歌唱：鋼琴彈清楚和弦，弦樂保持薄層，鼓手先用簡單 hi-hat。','Verse 2':'延續主歌但增加動態：鋼琴可加入分解音型，弦樂稍加厚，鼓組只加少量 kick。','Pre-Chorus':'逐小節增加力度：鋼琴加強低音根音，弦樂漸強，鼓手用 snare 邊擊或過門推向副歌。',Chorus:'完整呈現和聲：鋼琴保持和弦骨架，弦樂填滿中音域，鼓手使用 kick、snare 及適量 crash。','Chorus II':'在第一個副歌基礎上增加力度，但保持拍點清楚。','Chorus III':'維持高能量，鋼琴與弦樂不要互相搶中高音域。','Chorus IV':'延續最高層次，鼓手以穩定 groove 推進，不要過度加花。','尾句':'逐步減少音符密度；鋼琴保留最後和弦，弦樂漸弱，鼓手停止並一同收音。','尾句 II':'只保留必要的延音，跟隨整體速度放慢至結束。'}[sectionName]||'按譜面演奏，保持拍點、音域與動態清晰。';const cards=[['♬','鋼琴',`${info.piano||'按當前和弦彈奏'}。${direction}`],['◉','電子琴／弦樂',`${info.organ||'中音域長音托底'}。避免長時間佔用鋼琴旋律的中高音域。`],['♩','爵士鼓',`${info.drums||'按譜面鼓件演奏'}。先確認 kick／snare 的拍點，再按段落加入 hi-hat、ride 或 crash。`]];$('#live-position').textContent=section[0];$('#live-measure').textContent=`小節 ${measure}`;$('#arrangement-cards').innerHTML=cards.map((c,i)=>`<article class="arrangement-card ${trackEnabled[i]?'active':''}"><h3>${c[0]} ${c[1]}</h3><p>${esc(c[2])}</p></article>`).join('');}function syncUi(){position=Math.max(0,Math.min(100,positionSec/songSeconds*100));$('#progress').value=position;$('#current-time').textContent=`${Math.floor(positionSec/60)}:${String(Math.floor(positionSec%60)).padStart(2,'0')}`;const target=lyrics[Math.min(lyrics.length-1,Math.floor(positionSec/songSeconds*lyrics.length))];if(target)$('#player-lyric').textContent=target.text||'演唱對照';currentSection=Math.min(song.sections.length-1,Math.floor(positionSec/songSeconds*song.sections.length));const measure=Math.min(song.measureCount||137,Math.max(1,Math.floor(positionSec/songSeconds*(song.measureCount||137))+1));if(measure!==lastRenderedMeasure||currentSection!==lastRenderedSection){lastRenderedMeasure=measure;lastRenderedSection=currentSection;const section=song.sections[currentSection];$('#score-position').textContent=`目前位置：${section[0]} · 小節 ${section[1]}–${section[2]}`;renderSections();renderLiveArrangement(measure);syncScoreCursor();}}function tick(){if(!playing)return;positionSec=Math.min(songSeconds,positionSec+(performance.now()-playStartedAt)/1000*playRate);playStartedAt=performance.now();syncUi();if(positionSec>=songSeconds){playing=false;clearInterval(timer);silenceSynth();$('#play').textContent='▶';}}
$('#play').onclick=async()=>{
 if(playing){positionSec=Math.min(songSeconds,positionSec+(performance.now()-playStartedAt)/1000);playing=false;clearInterval(timer);silenceSynth();syncUi();$('#play').textContent='▶';return}
 const button=$('#play');
 button.disabled=true;
 try{
  $('#score-status').textContent='正在準備音色…';
  await playAudio();
  playing=true;
  button.textContent='Ⅱ';
  clearInterval(timer);
  timer=setInterval(tick,100);
 }catch(e){
  console.error(e);
  playing=false;
  clearInterval(timer);
  stopAudio();
  button.textContent='▶';
  $('#score-status').textContent='播放未開始：'+e.message;
 }finally{button.disabled=false}
};
$('#stop').onclick=()=>{playing=false;clearInterval(timer);silenceSynth();positionSec=0;syncUi();$('#play').textContent='▶';};$('#rewind').onclick=()=>{positionSec=Math.max(0,positionSec-5);if(playing)playAudio();syncUi()};$('#forward').onclick=()=>{positionSec=Math.min(songSeconds,positionSec+5);if(playing)playAudio();syncUi()};$('#progress').oninput=e=>{positionSec=+e.target.value/100*songSeconds;if(playing)playAudio();syncUi()};$('#bpm').oninput=e=>{const value=Number(e.target.value);$('#bpm-value').textContent=value;$('#tempo-mark').textContent=value;if(!playing)return;positionSec=Math.min(songSeconds,positionSec+(performance.now()-playStartedAt)/1000*playRate);playing=false;clearInterval(timer);silenceSynth();bpmChangePromise=bpmChangePromise.then(async()=>{await playAudio();if(!document.hidden){playing=true;playStartedAt=performance.now();clearInterval(timer);timer=setInterval(tick,100);}}).catch(error=>{$('#score-status').textContent='BPM 更新失敗：'+error.message});};$('#zoom-in').onclick=()=>{zoom=Math.min(120,zoom+10);if(osmd){osmd.zoom=zoom/100;osmd.render()}$('#zoom-label').textContent=zoom+'%'};$('#zoom-out').onclick=()=>{zoom=Math.max(80,zoom-10);if(osmd){osmd.zoom=zoom/100;osmd.render()}$('#zoom-label').textContent=zoom+'%'};renderAll();




































